{
    public override async ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData d, InterceptionResult<int> r, CancellationToken ct = default)
    {
        var db = (PaymentsDbContext)d.Context!;
        foreach (var e in db.ChangeTracker.Entries<Payment>().Where(e => e.State == EntityState.Modified && e.Entity.JustCaptured))
            await db.Database.ExecuteSqlAsync($"""
                MERGE read.MerchantDaily AS t USING (SELECT {e.Entity.MerchantId.Value} AS M, {e.Entity.CapturedOn} AS D) s ON t.MerchantId = s.M AND t.Day = s.D
                WHEN MATCHED THEN UPDATE SET Total = Total + {e.Entity.Captured.Amount}, Count = Count + 1
                WHEN NOT MATCHED THEN INSERT (MerchantId, Day, Total, Count) VALUES (s.M, s.D, {e.Entity.Captured.Amount}, 1);
                """, ct);
        return await base.SavingChangesAsync(d, r, ct);
    }
}

