public sealed record ApproveLoan(Guid LoanId, long ExpectedVersion, Guid CommandId);
public sealed record CommandOutcome(bool Ok, string? Error, long? Version);

public sealed class ApproveLoanHandler(ILoanRepository loans, IProcessedCommands processed, ILoanAuthorization authz,
                                       ICurrentUser user, IUnitOfWork uow)
{
    public async Task<CommandOutcome> Handle(ApproveLoan cmd, CancellationToken ct)
    {
        if (await processed.FindAsync(cmd.CommandId, ct) is { } previous) return previous;      // idempotent replay

        var loan = await loans.GetAsync(new LoanId(cmd.LoanId), ct);
        if (loan is null) return new(false, "loan.not_found", null);
        if (loan.Version != cmd.ExpectedVersion) return new(false, "loan.version_conflict", loan.Version);
        if (!await authz.CanApproveAsync(user, loan, ct)) return new(false, "loan.forbidden", null);

        var result = loan.Approve(user.Id);                                   // invariants + LoanApproved event
        if (result.IsFailure) return new(false, result.Error, loan.Version);

        var outcome = new CommandOutcome(true, null, loan.Version);
        processed.Record(cmd.CommandId, outcome);                             // same transaction
        await uow.SaveChangesAsync(ct);                                       // aggregate + outbox + idempotency record
        return outcome;
    }
}
