public sealed class MerchantPaymentsProjector(ReadDb db) :
    IEventHandler<PaymentAuthorisedV1>, IEventHandler<PaymentCapturedV1>, IEventHandler<PaymentRefundedV1>
{
    public async Task Handle(EventEnvelope<PaymentAuthorisedV1> e, CancellationToken ct)
    {
        var row = await db.MerchantPayments.FindAsync([e.Data.PaymentId], ct);
        if (row is not null && row.SourceVersion >= e.AggregateVersion) return;               // duplicate/stale
        row ??= db.MerchantPayments.Add(new MerchantPaymentRow { PaymentId = e.Data.PaymentId }).Entity;
        row.MerchantId = e.Data.MerchantId; row.Amount = e.Data.Amount; row.Currency = e.Data.Currency;
        row.Status = "Authorised"; row.CreatedUtc = e.OccurredAt.UtcDateTime; row.SourceVersion = e.AggregateVersion;
    }

    public async Task Handle(EventEnvelope<PaymentCapturedV1> e, CancellationToken ct)
    {
        var row = await db.MerchantPayments.FindAsync([e.Data.PaymentId], ct)
                  ?? throw new MissingPredecessorException(e.Data.PaymentId);                  // retry/park
        if (row.SourceVersion >= e.AggregateVersion) return;
        row.Status = "Captured"; row.SourceVersion = e.AggregateVersion;
    }

    public async Task Handle(EventEnvelope<PaymentRefundedV1> e, CancellationToken ct)
    {
        var row = await db.MerchantPayments.FindAsync([e.Data.PaymentId], ct) ?? throw new MissingPredecessorException(e.Data.PaymentId);
        if (row.SourceVersion >= e.AggregateVersion) return;
        row.RefundedAmount += e.Data.Amount; row.Status = row.RefundedAmount >= row.Amount ? "Refunded" : "PartiallyRefunded";
        row.SourceVersion = e.AggregateVersion;
    }
}
// The hosting consumer calls SaveChanges (rows + checkpoint) once per batch.
