// Counter projection: dedupe by event id in the same transaction
public sealed class MerchantDailyTotalsProjector(ReadDb db) : IEventHandler<PaymentCapturedV1>
{
    public async Task Handle(EventEnvelope<PaymentCapturedV1> e, CancellationToken ct)
    {
        db.ProcessedEvents.Add(new ProcessedEvent("MerchantDailyTotals", e.EventId));   // unique (Projection, EventId)
        await db.Database.ExecuteSqlAsync($"""
            UPDATE read.MerchantDaily SET Total = Total + {e.Data.Amount}, Count = Count + 1
            WHERE MerchantId = {e.Data.MerchantId} AND Day = {DateOnly.FromDateTime(e.OccurredAt.UtcDateTime)};
            IF @@ROWCOUNT = 0 INSERT read.MerchantDaily (MerchantId, Day, Total, Count)
                VALUES ({e.Data.MerchantId}, {DateOnly.FromDateTime(e.OccurredAt.UtcDateTime)}, {e.Data.Amount}, 1);
            """, ct);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException ex) when (ex.IsUniqueViolation()) { db.ChangeTracker.Clear(); /* duplicate: whole transaction rolled back */ }
    }
}

