public async Task<ApplyResult> ApplyAsync(IVersionedEvent e, CancellationToken ct)
{
    var row = await db.Accounts.FindAsync([e.AggregateId], ct);
    var stored = row?.SourceVersion ?? 0;
    if (e.AggregateVersion <= stored) return ApplyResult.Skipped;                         // duplicate or stale
    if (e.AggregateVersion > stored + 1)
    {
        db.ParkedEvents.Add(ParkedEvent.From(e, expected: stored + 1));                   // do not block other entities
        await db.SaveChangesAsync(ct);
        gapGauge.Record(1, new("projection", "AccountSummary"));
        return ApplyResult.Parked;
    }
    Projection.Apply(row ??= db.Accounts.Add(new AccountSummary { AccountId = e.AggregateId }).Entity, e);
    await db.SaveChangesAsync(ct);
    await DrainParkedAsync(e.AggregateId, ct);                                             // apply any parked successors now in sequence
    return ApplyResult.Applied;
}

