public sealed class SqlCheckpointedProjector(IConsumer<string, byte[]> consumer, IDbContextFactory<ReadDb> factory, IProjection projection)
{
    public async Task RunAsync(string topic, CancellationToken stop)
    {
        consumer.Subscribe(topic);
        consumer.Assign(await LoadOffsetsAsync(topic, stop));            // seek to our own checkpoints, not Kafka's

        while (!stop.IsCancellationRequested)
        {
            var batch = ConsumeBatch(consumer, max: 500, wait: TimeSpan.FromMilliseconds(200));
            if (batch.Count == 0) continue;
            await using var db = await factory.CreateDbContextAsync(stop);
            await using var tx = await db.Database.BeginTransactionAsync(stop);
            foreach (var m in batch) await projection.ApplyAsync(db, Deserialize(m), stop);
            foreach (var last in batch.GroupBy(m => m.TopicPartition).Select(g => g.Last()))
                await db.Checkpoints.UpsertAsync(projection.Name, last.TopicPartition, last.Offset.Value + 1, stop);
            await db.SaveChangesAsync(stop);
            await tx.CommitAsync(stop);                                   // rows + checkpoints atomically
        }
    }
}
