public sealed class IdempotencyStore(WriteDb db) : IIdempotencyStore
{
    public async Task<IdempotencyCheck> CheckAsync(TenantId t, Guid key, string requestHash, CancellationToken ct)
    {
        var rec = await db.Idempotency.AsNoTracking().SingleOrDefaultAsync(r => r.TenantId == t && r.Key == key, ct);
        if (rec is null) return IdempotencyCheck.New;
        if (rec.RequestHash != requestHash) return IdempotencyCheck.Mismatch;
        return rec.Outcome is null ? IdempotencyCheck.InProgress : IdempotencyCheck.Replay(rec.Outcome);
    }
    public void Record(TenantId t, Guid key, string requestHash, CommandOutcome outcome) =>
        db.Idempotency.Add(new IdempotencyRecord(t, key, requestHash, outcome, DateTimeOffset.UtcNow));   // committed with the state change
}

