// Synthetic end-to-end probe: write a probe command, measure until visible in the read model
public sealed class ProjectionFreshnessProbe(IProbeCommands commands, ReadDb read, TimeProvider clock) : BackgroundService
{
    private static readonly Histogram<double> Visibility = new Meter("ReadSide").CreateHistogram<double>("readside.visibility_ms");
    protected override async Task ExecuteAsync(CancellationToken stop)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(30), clock);
        while (await timer.WaitForNextTickAsync(stop))
        {
            var id = Guid.NewGuid(); var start = clock.GetTimestamp();
            await commands.CreateProbeAsync(id, stop);
            while (!await read.Probes.AnyAsync(p => p.Id == id, stop) && clock.GetElapsedTime(start) < TimeSpan.FromSeconds(60))
                await Task.Delay(100, clock, stop);
            Visibility.Record(clock.GetElapsedTime(start).TotalMilliseconds);
        }
    }
}
