public async Task ProcessAsync(ConsumeResult<string, byte[]> m, CancellationToken ct)
{
    var entityId = m.Message.Key;
    if (await blocked.IsBlockedAsync(Projection, entityId, ct)) { await parked.AddAsync(Projection, m, ct); return; }   // keep entity order

    for (var attempt = 1; ; attempt++)
    {
        try { await projector.ApplyAsync(Deserialize(m), ct); return; }
        catch (Exception ex) when (IsTransient(ex) && attempt < 5)
        { await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, attempt)), ct); }
        catch (Exception ex) when (!IsTransient(ex) || attempt >= 5)
        {
            await deadLetters.AddAsync(new DeadLetter(Projection, entityId, m.TopicPartitionOffset, ex.ToString(), m.Message.Value), ct);
            await blocked.BlockAsync(Projection, entityId, reason: ex.GetType().Name, ct);
            alerts.Raise($"Poison event for {Projection} entity {entityId}: {ex.GetType().Name}");
            return;                                                         // partition continues for other entities
        }
    }
}

