public sealed class PaymentCapturedUpcaster : IUpcaster
{
    public bool CanUpcast(string type, int version) => type == "PaymentCaptured" && version == 1;
    public (string Type, int Version, JsonObject Data) Upcast(JsonObject v1)
    {
        var amount = v1["amount"]!.GetValue<decimal>();
        var v2 = new JsonObject
        {
            ["paymentId"] = v1["paymentId"]!.DeepClone(),
            ["merchantId"] = v1["merchantId"]!.DeepClone(),
            ["gross"] = new JsonObject { ["amount"] = amount, ["currency"] = v1["currency"]!.DeepClone() },
            ["fee"] = new JsonObject { ["amount"] = 0m, ["currency"] = v1["currency"]!.DeepClone() },     // unknown in v1: documented default
            ["capturedAt"] = v1["capturedAt"]!.DeepClone()
        };
        return ("PaymentCaptured", 2, v2);
    }
}

