public sealed class Account : AggregateRoot<AccountId>
{
    public Money LedgerBalance { get; private set; }
    public Money HeldAmount { get; private set; }
    public Money OverdraftLimit { get; private set; }
    public Money Available => LedgerBalance.Subtract(HeldAmount).Add(OverdraftLimit);

