// Position projection per book: single writer, idempotent by trade version, snapshot for fast restart
public sealed class BookPositions
{
    private readonly Dictionary<string, Position> _byInstrument = new();
    private readonly Dictionary<Guid, long> _tradeVersions = new();
    public long LastOffset { get; private set; }

    public void Apply(TradeEvent e, long offset)
    {
        if (_tradeVersions.TryGetValue(e.TradeId, out var v) && e.Version <= v) return;            // duplicate or stale
        var previousQty = e is TradeAmended a ? a.PreviousQuantity * a.PreviousSideSign : 0m;
        var pos = _byInstrument.TryGetValue(e.Instrument, out var p) ? p : _byInstrument[e.Instrument] = new Position(e.Instrument);
        pos.Adjust(e switch
        {
            TradeBooked b => b.Quantity * b.SideSign,
            TradeAmended am => am.Quantity * am.SideSign - previousQty,
            TradeCancelled c => -c.Quantity * c.SideSign,
            _ => 0m
        });
        _tradeVersions[e.TradeId] = e.Version; LastOffset = offset;
    }

    public PositionSnapshot Snapshot() => new(_byInstrument.Values.Select(p => p.Clone()).ToList(), _tradeVersions.ToDictionary(), LastOffset);
}

// P&L recalculated on conflated prices and pushed per desk
decimal UnrealisedPnl(Position p, decimal lastPrice) => (lastPrice - p.AveragePrice) * p.Quantity;
