// Continuous reconciliation: projected balances vs ledger, alert on any mismatch
public sealed class BalanceReconciliation(LedgerReadDb ledger, ReadDb read, IAlerts alerts) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stop)
    {
        using var t = new PeriodicTimer(TimeSpan.FromMinutes(2));
        while (await t.WaitForNextTickAsync(stop))
        {
            var sample = await ledger.AccountBalances.OrderBy(_ => EF.Functions.Random()).Take(5_000)
                .Select(b => new { b.AccountId, b.Balance, b.LastPostingSeq }).ToListAsync(stop);
            var projected = await read.BalanceViews.Where(v => sample.Select(s => s.AccountId).Contains(v.AccountId))
                .ToDictionaryAsync(v => v.AccountId, stop);
            var mismatches = sample.Count(s => projected.TryGetValue(s.AccountId, out var p) && p.LastPostingSeq >= s.LastPostingSeq && p.Balance != s.Balance);
            if (mismatches > 0) alerts.Page("balance-projection-mismatch", $"{mismatches} of {sample.Count} sampled accounts differ from ledger");
        }
    }
}

