// Event-sourced payment with Marten: decide + append with expected version
public async Task<Result> Handle(RequestRefund cmd, IDocumentSession session, CancellationToken ct)
{
    var stream = await session.Events.FetchForWriting<PaymentState>(cmd.PaymentId, ct);   // optimistic concurrency on the stream
    var state = stream.Aggregate ?? throw new NotFoundException();
    var events = PaymentDecider.Decide(state, cmd);                                       // pure: state + command -> events
    if (events.IsFailure) return events.ToResult();
    stream.AppendMany(events.Value);
    await session.SaveChangesAsync(ct);                                                    // RefundRequested -> saga via integration stream
    return Result.Ok();
}

// Saga step: provider refund with idempotency, then ledger reversal
public async Task Handle(RefundRequestedV1 e, CancellationToken ct)
{
    var outcome = await provider.RefundAsync(e.ProviderRef, e.Amount, idempotencyKey: e.RefundId.ToString(), ct);
    await commands.SendAsync(outcome switch
