public sealed class DashboardProjector(IDbContextFactory<ReadDb> factory, IConsumer<string, byte[]> consumer, IDeadLetter dlq, IBusinessCalendar cal)
{
    public async Task RunAsync(CancellationToken stop)
    {
        while (!stop.IsCancellationRequested)
        {
            var msg = consumer.Consume(stop);
            try
            {
                await using var db = await factory.CreateDbContextAsync(stop);
                var env = Envelope.Parse(msg.Message.Value);
                db.ProcessedEvents.Add(new ProcessedEvent("dashboard", env.EventId));                   // dedupe, same transaction
                var day = cal.BusinessDate(env.OccurredAt, "Europe/London");
                var delta = env.Data switch { PaymentCapturedV2 c => c.Net.Amount, PaymentRefundedV1 r => -r.Amount, _ => 0m };
                await Upsert.MerchantDailyAsync(db, env.MerchantId, day, delta, stop);                  // insert-or-update
                await db.SaveChangesAsync(stop);
            }
            catch (DbUpdateException ex) when (ex.IsUniqueViolation()) { /* duplicate: already applied */ }
            catch (Exception ex) when (ex is not OperationCanceledException) { await dlq.SendAsync(msg, ex, stop); }
            consumer.Commit(msg);                                                                         // after processing
        }
    }
}
// Merchant names joined from a local lookup fed by MerchantRenamed events.
// Payout command reads the authoritative merchant balance aggregate, never this read model.
