// What a team writes with the platform framework: just the mapping
public sealed class MerchantPaymentsProjection : SqlProjection<MerchantPaymentRow>
{
    public MerchantPaymentsProjection()
    {
        Name = "merchant-payments";
        KeyedBy(e => e.PaymentId);                                   // ordering + idempotency per entity handled by the base
        On<PaymentAuthorisedV1>((row, e) => { row.MerchantId = e.MerchantId; row.Amount = e.Amount; row.Status = "Authorised"; });
        On<PaymentCapturedV2>((row, e) => row.Status = "Captured");
        On<PaymentRefundedV1>((row, e) => { row.RefundedAmount += e.Amount; row.Status = row.RefundedAmount >= row.Amount ? "Refunded" : "PartiallyRefunded"; });
        On<PersonalDataErasedV1>((row, e) => row.CustomerDisplayName = "Erased customer");
    }
}

builder.Services.AddProjectionPlatform(cfg)
    .AddSqlProjection<MerchantPaymentsProjection, ReadDb>(o => { o.Topic = "payments.v2"; o.BatchSize = 500; o.SloSeconds = 5; });

